-- public.plan_line(p_type text, p_material text, p_side text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.plan_line(p_type text, p_material text, p_side text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case when p_type = 'solid'
    then 'Planned: ' || lower(wt.name) || ' ' || lower(m.name) || ' wall, ' || side_name(p_side) || ' side.'
    when p_type = 'railing'
    then 'Planned: ' || lower(m.name) || ' railing, ' || side_name(p_side) || ' side.'
    else 'Planned: ' || lower(wt.name) || ', ' || lower(m.name) || ', ' || side_name(p_side) || ' side.' end
  from wall_type_def wt, build_material_def m where wt.id = p_type and m.id = p_material
$function$
